<?php
declare(strict_types=1);require_once __DIR__.'/../config/config.php';
function e($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}function go(string $url):never{header('Location: '.$url);exit;}function csrf():string{if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(32));return $_SESSION['csrf'];}function check_csrf():void{if(!hash_equals($_SESSION['csrf']??'',$_POST['csrf']??'')){http_response_code(419);exit('Invalid CSRF token.');}}function flash(string $t,string $m):void{$_SESSION['flash'][]=['type'=>$t,'message'=>$m];}function flashes():array{$x=$_SESSION['flash']??[];unset($_SESSION['flash']);return$x;}function money($v):string{return'PKR '.number_format((float)$v,0);}function current_user():?array{return$_SESSION['user']??null;}function require_login():array{$u=current_user();if(!$u)go('login.php');return$u;}function referral_url(string $code):string{return rtrim(APP_URL,' /').'/register.php?ref='.rawurlencode($code);}
